import{_ as e,o as a,c as r,ae as l}from"./chunks/framework.DI6M9D4h.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ems/index.md","filePath":"ems/index.md"}'),o={name:"ems/index.md"};function i(n,t,s,d,h,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<h2 id="beangle-ems" tabindex="-1">Beangle EMS <a class="header-anchor" href="#beangle-ems" aria-label="Permalink to &quot;Beangle EMS&quot;">​</a></h2><p>Beangle EMS（Enterprise Management System）是一个企业系统集成平台，提供统一的用户管理、安全认证、权限控制和系统配置能力。</p><h3 id="核心功能模块" tabindex="-1">核心功能模块 <a class="header-anchor" href="#核心功能模块" aria-label="Permalink to &quot;核心功能模块&quot;">​</a></h3><table class="table-api"><thead><tr><th>模块</th><th>描述</th></tr></thead><tbody><tr><td><strong>User</strong></td><td>用户管理，包括用户信息、角色、组织架构</td></tr><tr><td><strong>Security</strong></td><td>安全认证，包括菜单、权限、会话管理</td></tr><tr><td><strong>OA</strong></td><td>办公自动化，包括公告、文档、流程审批</td></tr><tr><td><strong>Config</strong></td><td>系统配置，包括域管理、数据源、应用管理</td></tr><tr><td><strong>Log</strong></td><td>日志管理，包括业务日志、错误日志</td></tr><tr><td><strong>CAS</strong></td><td>统一认证服务，支持 OAuth、单点登录</td></tr><tr><td><strong>WS</strong></td><td>RESTful Web 服务接口</td></tr></tbody></table><h3 id="架构特点" tabindex="-1">架构特点 <a class="header-anchor" href="#架构特点" aria-label="Permalink to &quot;架构特点&quot;">​</a></h3><ul><li><strong>统一认证</strong>：支持 CAS、OAuth、JWT 等多种认证方式</li><li><strong>多租户支持</strong>：支持多域名、多组织的隔离管理</li><li><strong>模块化设计</strong>：各功能模块松耦合，可独立部署</li><li><strong>RESTful API</strong>：提供完整的 Web 服务接口</li></ul><h3 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h3><h4 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h4><ul><li>用户信息管理（User、Profile、Avatar）</li><li>角色与权限（Role、RoleMember）</li><li>组织架构（Depart、Group、Dimension）</li></ul><h4 id="安全管理" tabindex="-1">安全管理 <a class="header-anchor" href="#安全管理" aria-label="Permalink to &quot;安全管理&quot;">​</a></h4><ul><li>功能权限（Menu、Resource、Permission）</li><li>数据权限（DataPermission）</li><li>会话管理（SessionInfo、SessionEvent）</li><li>OAuth 集成（OAuthCode、OAuthToken）</li></ul><h4 id="办公自动化" tabindex="-1">办公自动化 <a class="header-anchor" href="#办公自动化" aria-label="Permalink to &quot;办公自动化&quot;">​</a></h4><ul><li>公告通知（Notice）</li><li>文档管理（Doc）</li><li>流程审批（Flow、FlowTask）</li><li>消息服务（Message）</li></ul><h3 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to &quot;依赖关系&quot;">​</a></h3><ul><li><strong>Commons</strong>：核心工具库</li><li><strong>Security</strong>：安全框架</li><li><strong>WebMVC</strong>：Web 框架</li><li><strong>Data</strong>：数据访问</li><li><strong>Cache</strong>：缓存支持</li><li><strong>Notify</strong>：通知服务</li></ul><h3 id="典型应用场景" tabindex="-1">典型应用场景 <a class="header-anchor" href="#典型应用场景" aria-label="Permalink to &quot;典型应用场景&quot;">​</a></h3><ol><li><strong>统一身份认证</strong>：企业内部多个应用系统的统一登录</li><li><strong>权限管理</strong>：细粒度的功能权限和数据权限控制</li><li><strong>组织管理</strong>：企业组织架构和人员信息管理</li><li><strong>流程审批</strong>：各类业务流程的电子化审批</li></ol>',17)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
